'use client';
import React,{useState} from 'react';
import type {RecordRow as R} from '@/lib/erp-primitives';
import {day} from '@/lib/erp-primitives';
import {lifecycleStages,gateRequirements,documentUsable} from '@/lib/governance';
export default function ProjectGates({project:p,records,act,busy,onDocument}:{project:R;records:R[];act:(x:any)=>Promise<void>;busy:boolean;onDocument:(p:R,kind:string)=>void}){
const [ids,setIds]=useState<string[]>([]),[seenVersions,setSeenVersions]=useState<Record<string,number>>({}),[decision,setDecision]=useState(''),[confirmed,setConfirmed]=useState(false);
const stages=lifecycleStages[p.company],required=gateRequirements(p.company,p.lifecycleStage),docs=records.filter(r=>r.type==='document'&&r.projectId===p.id&&r.company===p.company&&documentUsable(r,day())),history=records.filter(r=>r.type==='project_gate'&&r.projectId===p.id&&r.company===p.company).sort((a,b)=>a.created.localeCompare(b.created)),missing=required.filter(k=>!docs.some(d=>ids.includes(d.id)&&d.documentKind===k));
return <section className="projectgates"><h3>Project evidence gates</h3>{!p.gatesEnabled?<><p className="notice">Existing delivery records are preserved. Enabling gates starts a new review sequence at Qualification.</p><button className="primary" disabled={busy||p.status==='Completed'} onClick={()=>act({action:'enable_gates',id:p.id,expectedVersion:p.version})}>Enable evidence gates</button></>:<><ol className="gatesteps">{stages.map(s=><li key={s} aria-current={p.lifecycleStage===s?'step':undefined}>{s}{history.some(g=>g.gateStage===s)?' · Approved':p.lifecycleStage===s?' · Current':''}</li>)}</ol>{p.status!=='Completed'&&<form onSubmit={e=>{e.preventDefault();act({action:'advance_gate',id:p.id,expectedVersion:p.version,documentIds:ids,documentVersions:seenVersions,decision,confirmed})}}><h4>Review {p.lifecycleStage}</h4><p>Required evidence: {required.join(', ')}.</p><div className="recordactions">{required.map(k=><button type="button" className="secondary" key={k} onClick={()=>onDocument(p,k)}>Register {k.toLowerCase()}</button>)}</div>{docs.map(d=><label key={d.id} className="officepermission"><input type="checkbox" disabled={busy} checked={ids.includes(d.id)} onChange={e=>{setIds(x=>e.target.checked?[...x,d.id]:x.filter(id=>id!==d.id));setSeenVersions(x=>({...x,[d.id]:d.version}));}}/>{d.documentCode} · {d.name} · {d.documentKind} · Revision {d.revisionLabel}{ids.includes(d.id)&&seenVersions[d.id]!==d.version?' · Changed since selection; review and select again':''}</label>)}{!docs.length&&<p className="empty">Register and verify the required project documents before approving this gate.</p>}<label>Approval decision and acceptance checks<textarea required rows={3} value={decision} onChange={e=>setDecision(e.target.value)}/></label><label className="officepermission"><input type="checkbox" checked={confirmed} onChange={e=>setConfirmed(e.target.checked)}/>I reviewed the actual evidence and approve this stage</label><button className="primary" disabled={busy||!confirmed||!ids.length||!decision.trim()||missing.length>0||p.status==='On hold'}>{busy?'Saving…':p.lifecycleStage===stages.at(-1)?'Approve final gate and complete':'Approve gate and advance'}</button>{missing.length>0&&<p className="footnote">Select verified evidence for: {missing.join(', ')}.</p>}</form>}</>}<h4>Approval history</h4>{history.map(g=><details key={g.id} className="technicallog"><summary>{g.gateStage} · {g.approvedBy} · {g.date}</summary><p>{g.decision}</p><p>Next stage: {g.nextStage}</p><ul>{g.evidence.map((e:any)=>{const current=records.find(r=>r.id===e.id&&r.company===p.company);return <li key={e.id}>{e.documentCode} · {e.kind} · Version {e.version}{current?.version!==e.version||!documentUsable(current,day())?' · Source has changed or needs review':''}</li>})}</ul></details>)}{!history.length&&<p className="footnote">No evidence gates approved yet.</p>}</section>;
}
